vertex:
vec2 hm_uv = vec2(
    (VERTEX.x + 80.0 * 0.5) / 80.0,
    1.0 - (VERTEX.z + 80.0 * 0.5) / 80.0
);
float _h_center = texture(heightmap, hm_uv).r + -0.5;
VERTEX.y += _h_center * 0.6;
float _eps_uv = 1.0 / 1024.0;
float _h_xp = texture(heightmap, hm_uv + vec2(_eps_uv, 0.0)).r + -0.5;
float _h_xn = texture(heightmap, hm_uv - vec2(_eps_uv, 0.0)).r + -0.5;
float _h_zp = texture(heightmap, hm_uv + vec2(0.0, _eps_uv)).r + -0.5;
float _h_zn = texture(heightmap, hm_uv - vec2(0.0, _eps_uv)).r + -0.5;
float _ds = 2.0 * _eps_uv * 80.0;
vec3 _slope_x = vec3(_ds, (_h_xp - _h_xn) * 0.6, 0.0);
vec3 _slope_z = vec3(0.0, (_h_zp - _h_zn) * 0.6, _ds);
NORMAL = normalize(cross(_slope_z, _slope_x));
v_world_pos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
vec3 world_pos_local = v_world_pos;

fragment:
vec2 biome_uv = vec2(
    (v_world_pos.x + 80.0 * 0.5) / 80.0,
    1.0 - (v_world_pos.z + 80.0 * 0.5) / 80.0
);
vec3 biome_probe = texture(biome_map, biome_uv).rgb;
float d_dirt = distance(biome_probe, vec3(0.659, 0.537, 0.353));
float d_grass = distance(biome_probe, vec3(0.627, 0.847, 0.439));
float d_water = distance(biome_probe, vec3(0.188, 0.439, 0.753));
float d_path = distance(biome_probe, vec3(0.784, 0.659, 0.471));
float d_forest = distance(biome_probe, vec3(0.165, 0.353, 0.165));
float w_dirt = pow(max(0.001, 0.1 - d_dirt), 2.0);
float w_grass = pow(max(0.001, 0.1 - d_grass), 2.0);
float w_water = pow(max(0.001, 0.1 - d_water), 2.0);
float w_path = pow(max(0.001, 0.1 - d_path), 2.0);
float w_forest = pow(max(0.001, 0.1 - d_forest), 2.0);
float wsum = w_dirt + w_grass + w_water + w_path + w_forest;
vec2 _tile_uv = UV * 30.0;
vec2 _anim_uv = _tile_uv + vec2(
    sin(TIME * 0.15 + v_world_pos.x * 0.18) * 0.06,
    cos(TIME * 0.15 * 0.73 + v_world_pos.z * 0.18) * 0.06
);
vec3 a_dirt = texture(albedo_dirt, _tile_uv).rgb;
vec3 a_grass = texture(albedo_grass, _tile_uv).rgb;
vec3 a_water = texture(albedo_water, _anim_uv).rgb;
vec3 a_path = texture(albedo_path, _tile_uv).rgb;
vec3 a_forest = texture(albedo_forest, _tile_uv).rgb;
ALBEDO = (a_dirt * w_dirt
        + a_grass * w_grass
        + a_water * w_water
        + a_path * w_path
        + a_forest * w_forest) / wsum;
ROUGHNESS = (0.92 * w_dirt
        + 0.95 * w_grass
        + 0.25 * w_water
        + 0.8 * w_path
        + 0.9 * w_forest) / wsum;
METALLIC = (0.0 * w_dirt
        + 0.0 * w_grass
        + 0.05 * w_water
        + 0.0 * w_path
        + 0.0 * w_forest) / wsum;

uniforms:
uniform sampler2D albedo_dirt : source_color, filter_linear_mipmap, repeat_enable;
uniform sampler2D albedo_forest : source_color, filter_linear_mipmap, repeat_enable;
uniform sampler2D albedo_grass : source_color, filter_linear_mipmap, repeat_enable;
uniform sampler2D albedo_path : source_color, filter_linear_mipmap, repeat_enable;
uniform sampler2D albedo_water : source_color, filter_linear_mipmap, repeat_enable;
uniform sampler2D biome_map : source_color, filter_linear, repeat_disable;
uniform sampler2D heightmap : source_color, filter_linear, repeat_disable;

// Per-biome reference colors (from spec)
const vec3 BIOME_COLOR_DIRT = vec3(0.659, 0.537, 0.353);
const vec3 BIOME_COLOR_GRASS = vec3(0.627, 0.847, 0.439);
const vec3 BIOME_COLOR_WATER = vec3(0.188, 0.439, 0.753);
const vec3 BIOME_COLOR_PATH = vec3(0.784, 0.659, 0.471);
const vec3 BIOME_COLOR_FOREST = vec3(0.165, 0.353, 0.165);
